'use server';

import { redirect } from 'next/navigation';

import {
  isValidDeviceCode,
  isValidUuid,
  sha256Hex,
} from '@/lib/auth/desktop-tokens';
import { logSafe } from '@/lib/http';
import { supabaseAdmin } from '@/lib/supabase/admin';
import { createSupabaseRouteClient } from '@/lib/supabase/route';

/** Same TTL as the desktop flow (migration 003). */
const LINK_CODE_TTL_MS = 10 * 60 * 1000;

/**
 * Approve a browser-extension sign-in.
 *
 * WHY THIS IS A POST (a server action) AND NOT DONE ON PAGE LOAD
 *
 * The device code in the URL was generated by whoever built the link. If simply
 * VISITING `/auth/extension?device_code=X` approved it, an attacker could send a
 * signed-in user a link carrying a code the attacker generated, then redeem it at
 * /api/desktop/exchange and receive tokens for the victim's account. Requiring an
 * explicit click on a same-origin form closes that: Next.js server actions reject
 * cross-origin submissions, and the Supabase session cookie is SameSite=Lax, so a
 * forged cross-site POST arrives unauthenticated.
 */
export async function approveExtension(formData: FormData): Promise<void> {
  const deviceCode = formData.get('device_code');
  const deviceId = formData.get('device_id');
  if (!isValidDeviceCode(deviceCode) || !isValidUuid(deviceId)) {
    redirect('/login');
  }

  const sb = await createSupabaseRouteClient();
  const {
    data: { user },
  } = await sb.auth.getUser();
  if (!user) {
    const ret = encodeURIComponent(
      `/auth/extension?device_code=${deviceCode}&device_id=${deviceId}`
    );
    redirect(`/login?redirectedFrom=${ret}`);
  }

  const { error } = await supabaseAdmin()
    .from('desktop_link_codes')
    .insert({
      user_id: user.id,
      device_code_hash: sha256Hex(deviceCode as string),
      device_id: deviceId,
      expires_at: new Date(Date.now() + LINK_CODE_TTL_MS).toISOString(),
    });

  if (error) {
    // 23505: this code was already approved (double click, back button). The
    // extension can still redeem the existing row, so treat it as success.
    if (error.code !== '23505') {
      logSafe('extension_link_insert_failed', {
        user_id: user.id,
        error: error.message,
      });
      redirect('/auth/extension/done?status=error');
    }
  }

  // The extension watches for this URL on the tab it opened, then redeems the
  // code it generated at /api/desktop/exchange.
  redirect('/auth/extension/done');
}
